</span></div></footer><script>(function(){const nav=document.getElementById('kbLinks'),menu=document.getElementById('kbMenu'),side=document.getElementById('kbSide'),overlay=document.getElementById('sideOverlay'),browse=document.getElementById('browseBtn');menu?.addEventListener('click',()=>{const x=nav.classList.toggle('open');menu.setAttribute('aria-expanded',x?'true':'false')});function closeSide(){side.classList.remove('open');overlay.classList.remove('open')}browse?.addEventListener('click',()=>{side.classList.add('open');overlay.classList.add('open')});overlay?.addEventListener('click',closeSide);side?.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeSide));const q=document.getElementById('kbSearch'),cards=[...document.querySelectorAll('.card')];q.addEventListener('input',()=>{const v=q.value.toLowerCase().trim();cards.forEach(c=>c.hidden=!!v&&!c.dataset.search.includes(v))});})();</script></body></html>
